package cue

import (
	_ "embed"
	"errors"
	"fmt"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	cueerrors "cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
	yamlv3 "gopkg.in/yaml.v3"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New("validation failed")
)

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

type validationErrors []error

func (e validationErrors) Error() string        { return ErrValidationFailed.Error() }
func (e validationErrors) Unwrap() []error      { return []error(e) }
func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }

// Unwrap returns the individual errors in a validation error.
func Unwrap(err error) ([]error, bool) {
	var multi interface{ Unwrap() []error }
	if !errors.As(err, &multi) {
		return nil, false
	}
	return multi.Unwrap(), true
}

type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil {
		return nil, v.Err()
	}

	return &FeaturesValidator{
		cue: cctx,
		v:   v,
	}, nil
}

// Validate validates a YAML file against our cue definition of features.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	var problems validationErrors

	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}

	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return err
	}

	err = v.v.
		Unify(yv).
		Validate(cue.All(), cue.Concrete(true))

	for _, e := range cueerrors.Errors(err) {
		problem := Error{
			Message: e.Error(),
			Location: Location{
				File: file,
			},
		}

		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			problem.Location.Line = p.Line()
			problem.Location.Column = p.Column()
		}

		problems = append(problems, problem)
	}

	var doc yamlv3.Node
	if err := yamlv3.Unmarshal(b, &doc); err == nil {
		problems = append(problems, referenceErrors(file, &doc)...)
	} else if len(problems) == 0 {
		return err
	}

	if len(problems) > 0 {
		return problems
	}
	return nil
}

// field finds a value in a YAML mapping, preserving the source node's position.
func field(mapping *yamlv3.Node, key string) *yamlv3.Node {
	if mapping == nil || mapping.Kind != yamlv3.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(mapping.Content); i += 2 {
		if mapping.Content[i].Value == key {
			return mapping.Content[i+1]
		}
	}
	return nil
}

func sequence(node *yamlv3.Node) []*yamlv3.Node {
	if node != nil && node.Kind == yamlv3.SequenceNode {
		return node.Content
	}
	return nil
}

func referenceErrors(file string, doc *yamlv3.Node) []error {
	if len(doc.Content) == 0 {
		return nil
	}
	root := doc.Content[0]
	namespace := "default"
	if n := field(root, "namespace"); n != nil && n.Value != "" {
		namespace = n.Value
	}

	segments := make(map[string]bool)
	for _, segment := range sequence(field(root, "segments")) {
		if key := field(segment, "key"); key != nil {
			segments[key.Value] = true
		}
	}

	var problems []error
	checkSegment := func(flag string, index int, node *yamlv3.Node) {
		if node != nil && node.Kind == yamlv3.ScalarNode && !segments[node.Value] {
			problems = append(problems, Error{
				Message:  fmt.Sprintf("flag %s/%s rule %d references unknown segment %q", namespace, flag, index, node.Value),
				Location: Location{File: file, Line: node.Line, Column: node.Column},
			})
		}
	}
	for _, flag := range sequence(field(root, "flags")) {
		key := field(flag, "key")
		if key == nil {
			continue
		}
		variants := make(map[string]bool)
		for _, variant := range sequence(field(flag, "variants")) {
			if variantKey := field(variant, "key"); variantKey != nil {
				variants[variantKey.Value] = true
			}
		}
		for i, rule := range sequence(field(flag, "rules")) {
			segment := field(rule, "segment")
			if segment != nil && segment.Kind == yamlv3.MappingNode {
				for _, item := range sequence(field(segment, "keys")) {
					checkSegment(key.Value, i, item)
				}
			} else {
				checkSegment(key.Value, i, segment)
			}
			for _, distribution := range sequence(field(rule, "distributions")) {
				variant := field(distribution, "variant")
				if variant != nil && variant.Kind == yamlv3.ScalarNode && !variants[variant.Value] {
					problems = append(problems, Error{
						Message:  fmt.Sprintf("flag %s/%s rule %d references unknown variant %q", namespace, key.Value, i, variant.Value),
						Location: Location{File: file, Line: variant.Line, Column: variant.Column},
					})
				}
			}
		}
		for i, rollout := range sequence(field(flag, "rollouts")) {
			segment := field(rollout, "segment")
			checkSegment(key.Value, i, field(segment, "key"))
			for _, item := range sequence(field(segment, "keys")) {
				checkSegment(key.Value, i, item)
			}
		}
	}
	return problems
}
